events = [(1, 'ok'), (3, 'err'), (6, 'ok'), (8, 'err'), (11, 'err')]  # (ts, status)
SIZE = 5

tumbling = {}
for ts, s in events:
    w = (ts // SIZE) * SIZE
    tumbling.setdefault(w, []).append(s)
print('tumbling 5s windows:')
for w in sorted(tumbling):
    errs = tumbling[w].count('err')
    print('  [%d,%d): %d events, %d errors' % (w, w + SIZE, len(tumbling[w]), errs))

versions = {  # key -> [(commit_ts, value)], newest last
    'config': [(1, 'v1'), (5, 'v2'), (9, 'v3')],
}

def as_of(key, t):
    best = None
    for ts, val in versions[key]:
        if ts <= t:
            best = val
    return best

for t in (3, 7, 12):
    print('as of t=%d: config=%s' % (t, as_of('config', t)))
