# price list versions: (valid_from, valid_to, price)
prices = [(1, 10, 9.99), (10, 20, 12.99), (20, 99, 11.49)]
orders = [(5, 'o1'), (15, 'o2'), (25, 'o3')]  # (ts, id)

def price_at(ts):
    return next(p for f, t, p in prices if f <= ts < t)

for ts, oid in orders:
    print('order %s at t=%2d -> price %.2f (list in effect then, not today)' % (oid, ts, price_at(ts)))

import hashlib

def route(ts, key):
    bucket = 'hot' if ts >= 90 else 'cold'          # time dimension first
    shard = int(hashlib.md5(key.encode()).hexdigest(), 16) % 4
    tier = {'hot': 'nvme', 'cold': 'hdd'}[bucket]
    return '%s-%d (%s)' % (bucket, shard, tier)

for ts, k in [(95, 'e1'), (99, 'e2'), (10, 'e3'), (50, 'e4')]:
    print('t=%2d %-3s -> %s' % (ts, k, route(ts, k)))
